-- 133: Original BrillaPrep WASSCE BrillaPrep transitional Applied Electricity beta content blueprint beta questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_133_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_133_guard;
INSERT INTO _migration_133_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_016' AND NOT (q.topic_id IS 'topic_was_elect_4' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A compass is placed beside a straight wire and deflects when the wire is energised. What produced the deflection?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Its resistance must become zero","B. All nearby metals become permanent magnets","C. Voltage can no longer be measured","D. A magnetic field is produced"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Moving electric charge produces a magnetic field whose direction around a straight conductor follows the right-hand grip rule. Therefore the correct answer is D: A magnetic field is produced.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_016' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_133_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_017' AND NOT (q.topic_id IS 'topic_was_elect_4' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A coil is moved through a magnetic field and a voltmeter briefly deflects. Which process produced the emf?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Production of an emf when magnetic flux linkage changes","B. Creation of energy without a source","C. Permanent charging of every iron core","D. Conversion of resistance directly into mass"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Faraday’s law relates induced emf to the rate of change of magnetic flux linkage through a circuit. Therefore the correct answer is A: Production of an emf when magnetic flux linkage changes.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_017' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_133_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_018' AND NOT (q.topic_id IS 'topic_was_elect_4' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a transformer core laminated?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To increase winding resistance deliberately","B. To reduce eddy-current losses","C. To stop magnetic flux entirely","D. To convert AC directly into DC"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Thin insulated laminations interrupt circulating currents in the core, reducing heating and wasted power. Therefore the correct answer is B: To reduce eddy-current losses.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_018' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_133_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_019' AND NOT (q.topic_id IS 'topic_was_elect_4' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An ideal transformer has 100 primary turns and 20 secondary turns with 240 V applied. What is the secondary voltage?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 12 V","B. 120 V","C. 48 V","D. 1200 V"]' AND q.correct_answer IS 'C' AND q.explanation IS 'For an ideal transformer, Vs divided by Vp equals Ns divided by Np. Thus 240 multiplied by 20 over 100 equals 48 volts. Therefore the correct answer is C: 48 V.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_019' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_133_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_020' AND NOT (q.topic_id IS 'topic_was_elect_4' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why does a transformer require a changing magnetic flux?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Steady DC automatically produces continuous secondary voltage","B. Flux must remain zero for energy transfer","C. The core supplies unlimited electrical energy","D. A changing flux is needed to induce emf in the secondary winding"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Mutual induction depends on changing flux linkage, which is why ordinary transformers operate with alternating rather than steady direct current. Therefore the correct answer is D: A changing flux is needed to induce emf in the secondary winding.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_020' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
